package app.goodboy13.bignotes.core.eraser

import app.goodboy13.bignotes.core.gl.CanvasMutation
import app.goodboy13.bignotes.core.history.CanvasAction
import app.goodboy13.bignotes.core.model.EraserMode
import app.goodboy13.bignotes.core.model.Stroke

/**
 * Encapsulates an active vector eraser session.
 *
 * Tracks the net delta between original untouched strokes intersected during the swipe
 * and any live sub-strokes generated by precision cuts. On session completion, produces
 * a single atomic [CanvasAction] and [CanvasMutation] rather than flooding history at 60-120Hz.
 */
class EraserSession(val mode: EraserMode) {

    private val originalErasedStrokes = mutableMapOf<String, Stroke>()
    private val liveSubStrokes = mutableMapOf<String, Stroke>()

    val hasModifications: Boolean
        get() = originalErasedStrokes.isNotEmpty()

    /**
     * Records a whole stroke that was erased during this session.
     */
    fun recordWholeStrokeErased(stroke: Stroke) {
        if (stroke.id in liveSubStrokes) {
            // This stroke was a split fragment produced earlier in the same swipe session
            liveSubStrokes.remove(stroke.id)
        } else {
            // First time intersecting an existing canvas stroke
            originalErasedStrokes[stroke.id] = stroke
        }
    }

    /**
     * Records a precision cut on a stroke, replacing it with 0..N sub-strokes.
     */
    fun recordPrecisionCut(cutStroke: Stroke, subStrokes: List<Stroke>) {
        if (cutStroke.id in liveSubStrokes) {
            // Further cut on a sub-stroke created earlier in this session
            liveSubStrokes.remove(cutStroke.id)
        } else {
            // First time cutting this original stroke
            originalErasedStrokes[cutStroke.id] = cutStroke
        }

        for (sub in subStrokes) {
            liveSubStrokes[sub.id] = sub
        }
    }

    /**
     * Resolves the final atomic undo/redo action for this eraser session.
     * Returns null if no strokes were altered.
     */
    fun createFinalAction(): CanvasAction? {
        if (originalErasedStrokes.isEmpty()) return null
        val removedList = originalErasedStrokes.values.toList()
        val addedList = liveSubStrokes.values.toList()
        return if (addedList.isNotEmpty()) {
            CanvasAction.ReplaceStrokes(removedList, addedList)
        } else {
            CanvasAction.RemoveStrokes(removedList)
        }
    }

    /**
     * Resolves the final canvas mutation for subscribers.
     */
    fun createFinalMutation(): CanvasMutation? {
        if (originalErasedStrokes.isEmpty()) return null
        val removedIds = originalErasedStrokes.keys.toList()
        val addedList = liveSubStrokes.values.toList()
        return if (addedList.isNotEmpty()) {
            CanvasMutation.Replaced(removedIds, addedList)
        } else {
            CanvasMutation.Removed(removedIds)
        }
    }

    fun clear() {
        originalErasedStrokes.clear()
        liveSubStrokes.clear()
    }
}
